const renalPulmQuestions = [
  // ===== RENAL: Glomerular - Nephritic =====
  { id: "rp1", category: "Glomerular", q: "Four classic findings of nephrotic syndrome?", a: "Proteinuria (>3g/24h), hypoalbuminemia, peripheral edema, hyperlipidemia. Proteinuria -> hypoalbuminemia -> decreased intravascular oncotic pressure -> edema. Liver exports more apolipoproteins to compensate for low albumin -> hyperlipidemia." },
  { id: "rp2", category: "Glomerular", q: "Four classic findings of nephritic syndrome?", a: "Hematuria, oliguria (<400 mL/24h in adults), azotemia (high BUN), hypertension. HTN is from microvascular disruption plus RAAS upregulation - per Mehlman, angiotensin-II is probably more responsible than aldosterone since AT-II is a potent systemic vasoconstrictor." },
  { id: "rp3", category: "Glomerular", q: "Is there proteinuria in nephritic syndrome, and what is THE differentiator from nephrotic?", a: "Almost always yes, just less than in nephrotic. The key differentiator is blood in the urine - nephritic has it, nephrotic does not." },
  { id: "rp4", category: "Glomerular", q: "Subepithelial vs subendothelial deposits - what is the one-line rule?", a: "If the condition has 'proliferative' in the name, it has SUBENDOTHELIAL deposits. No 'proliferative' in the name means not subendothelial. So MPGN and DPGN = subendothelial. Per Mehlman, this is the trick worth memorizing." },
  { id: "rp5", category: "Glomerular", q: "Important nephrotic syndromes for USMLE?", a: "Membranous glomerulonephropathy, minimal change disease (lipoid nephrosis), FSGS, renal amyloidosis, diabetic glomerulonephropathy." },
  { id: "rp6", category: "Glomerular", q: "Important nephritic syndromes for USMLE?", a: "IgA nephropathy (Berger disease) and post-streptococcal glomerulonephritis (PSGN)." },
  { id: "rp7", category: "Glomerular", q: "A 12-year-old boy has a sore throat, then blood in the urine 1-3 days later. Diagnosis?", a: "IgA nephropathy, NOT PSGN. Synpharyngitic hematuria (days, not weeks) = IgA. Per Mehlman this distinction is mega-high-yield." },
  { id: "rp8", category: "Glomerular", q: "A 12-year-old boy has a sore throat, then blood in the urine 1-2 weeks later. Diagnosis?", a: "PSGN. The 1-2 week latency is the tell; 1-3 days is IgA nephropathy." },
  { id: "rp9", category: "Glomerular", q: "A 12-year-old boy has a viral infection, then red urine 2 days later. Renal biopsy finding?", a: "IgA deposition in the mesangium (IgA nephropathy)." },
  { id: "rp10", category: "Glomerular", q: "A 12-year-old boy has a GI infection with diarrhea, then red urine 2 days later. Diagnosis?", a: "IgA nephropathy. GI or viral trigger with hematuria within days = IgA, same as after pharyngitis." },
  { id: "rp11", category: "Glomerular", q: "A 3-year-old girl has violaceous lesions on buttocks and thighs, arthralgias, abdominal pain, and red urine. Renal diagnosis?", a: "IgA nephropathy. The tetrad is Henoch-Schonlein purpura; the renal component IS IgA nephropathy. Per Mehlman, HSP and IgA nephropathy are the same disease spectrum - immune complexes in skin (purpura), joints (arthritis), mesentery (abdominal pain). HSP is pediatric; IgA nephropathy occurs easily in adults." },
  { id: "rp12", category: "Glomerular", q: "A 12-year-old girl has crusty yellow lesions around the mouth for a week and today has red urine. Diagnosis and treatment of the trigger?", a: "PSGN secondary to impetigo -> topical mupirocin for the impetigo. Group A Strep skin infections (impetigo, cellulitis, erysipelas) can cause PSGN. Rheumatic heart disease does NOT follow cutaneous Strep - only pharyngitis." },
  { id: "rp13", category: "Glomerular", q: "A 28-year-old man has blurry vision and/or hearing problems plus red urine. Diagnosis and inheritance?", a: "Alport syndrome, X-linked RECESSIVE. Per Mehlman: FA2020 says X-linked dominant but retired NBME 19 says X-linked recessive, and the NBME always wins." },
  { id: "rp14", category: "Glomerular", q: "Mechanism of Alport syndrome, and how does it contrast with Goodpasture?", a: "Alport = MUTATION in type IV collagen (COL4A3/4/5). Goodpasture = ANTIBODIES against type IV collagen. Type IV collagen matters in the lens, cochlear stereocilia, and glomerular basement membrane -> 'eye and/or ear problem plus red urine' in a male." },
  { id: "rp15", category: "Glomerular", q: "A 13-year-old boy has a URTI, red urine one week later, and decreased C3. What answer might the NBME use instead of PSGN?", a: "'Acute glomerulonephritis' - same thing. On a 2CK NBME the listed answer is simply acute glomerulonephritis, which throws people off." },
  { id: "rp16", category: "Glomerular", q: "PSGN renal biopsy shows what?", a: "Subepithelial deposits. Per Mehlman, the 'lumpy bumpy' phrase is perpetuated in FA but never actually shows up in NBME material." },
  { id: "rp17", category: "Glomerular", q: "When is membranoproliferative glomerulonephritis (MPGN) the answer?", a: "Subendothelial deposits, dense deposits (dense deposit disease), C3 nephritic factor, duplication or splitting of the glomerular basement membrane ('tram-track'), or a nephritic picture in someone with hepatitis C." },
  { id: "rp18", category: "Glomerular", q: "When is diffuse proliferative glomerulonephritis (DPGN) the answer?", a: "SLE. They will also mention 'capillary looping.' DPGN is subendothelial like MPGN, but lupus is the setting." },
  { id: "rp19", category: "Glomerular", q: "When is rapidly progressive glomerulonephritis (RPGN) the answer, and what is on biopsy?", a: "Acute deterioration in renal function (high Cr, high BUN, oliguria) in someone with a vasculitis (granulomatosis with polyangiitis, eosinophilic granulomatosis with polyangiitis, microscopic polyangiitis) or Goodpasture. Biopsy: fibrin crescents, parietal cell hyperplasia, leukocytic infiltrate. On Step 1, know the crescents are made of FIBRIN." },
  { id: "rp20", category: "Vasculitis + Renal", q: "In granulomatosis with polyangiitis (Wegener), what does the renal biopsy often show?", a: "'Necrotizing' glomerulonephritis." },
  { id: "rp21", category: "Vasculitis + Renal", q: "ANCA associations: Wegener vs Churg-Strauss vs microscopic polyangiitis?", a: "Wegener = c-ANCA (anti-proteinase 3 / anti-PR3). Churg-Strauss and microscopic polyangiitis = p-ANCA (anti-myeloperoxidase / anti-MPO). Real life has overlap and ANCA-negative patients, but on the USMLE the classic associations hold." },
  { id: "rp22", category: "Vasculitis + Renal", q: "Mechanism and diagnosis of Goodpasture syndrome?", a: "Antibodies against the alpha-3 chains of type IV collagen (anti-GBM). NBME phrases the mechanism as 'autoantibodies against host cell basement membranes.' Biopsy shows LINEAR immunofluorescence. Presents as a 40s male with hemoptysis plus hematuria." },
  { id: "rp23", category: "Vasculitis + Renal", q: "How does Wegener present clinically?", a: "Hematuria plus hemoptysis plus 'head'-itis - any head finding: nasal septal perforation, mastoiditis, otitis, sinusitis." },
  { id: "rp24", category: "Vasculitis + Renal", q: "How do Churg-Strauss and microscopic polyangiitis present?", a: "Churg-Strauss: asthma plus eosinophilia, head findings rare. Microscopic polyangiitis: just hematuria, almost always." },
  { id: "rp25", category: "Vasculitis + Renal", q: "Wrist-drop or foot-drop in someone with Wegener, Churg-Strauss, or microscopic polyangiitis. Diagnosis?", a: "Mononeuritis multiplex - palsy of one large nerve in multiple locations, classically radial or common peroneal." },
  { id: "rp26", category: "Vasculitis + Renal", q: "A 44-year-old man has hematuria and hemoptysis. Sort the three variants: no other findings; necrotizing glomerulonephritis on biopsy; linear immunofluorescence on biopsy.", a: "No other findings -> Goodpasture most likely. Necrotizing glomerulonephritis -> Wegener. Linear immunofluorescence -> Goodpasture (confirmed)." },
  { id: "rp27", category: "Vasculitis + Renal", q: "A 38-year-old woman has hematuria. Match the antibody: anti-PR3; c-ANCA plus nasal septal perforation; p-ANCA; anti-MPO.", a: "Anti-PR3 -> Wegener. c-ANCA plus nasal septal perforation -> Wegener. p-ANCA -> microscopic polyangiitis. Anti-MPO -> microscopic polyangiitis." },
  { id: "rp28", category: "Glomerular", q: "A 12-year-old boy has periorbital edema and red urine with low C3 - versus periorbital edema with NO blood in the urine. Two diagnoses?", a: "With red urine and low C3 -> PSGN. Without blood in the urine -> minimal change disease (lipoid nephrosis)." },
  { id: "rp29", category: "Glomerular", q: "A 40-year-old with Hodgkin lymphoma develops a nephrotic picture with no blood in the urine. Diagnosis and treatment?", a: "Minimal change disease. MCD is almost always children after a viral infection, but it is also seen in adults with Hodgkin. Treat with steroids - highly effective." },
  { id: "rp30", category: "Glomerular", q: "Sickle cell, HIV / IV drug use, or interferon use plus nephrotic syndrome. Diagnosis and treatment?", a: "FSGS. Treat with steroids, though not as effective as in minimal change disease." },
  { id: "rp31", category: "Glomerular", q: "What does 'focal segmental' actually mean in FSGS?", a: "Focal = part of the kidney (vs diffuse = whole kidney). Segmental = part of a single nephron (vs global = an entire nephron). So parts of some nephrons are involved - which fits sickle cell, where sickling causes irregular, non-uniform microvascular damage." },
  { id: "rp32", category: "Glomerular", q: "Sulfa drug plus a kidney issue with no blood in the urine. Diagnosis and biopsy?", a: "Membranous glomerulonephropathy. Biopsy: subepithelial deposits. 'Spike and dome' is Qbank buzz, not NBME. Hepatitis B (more than C) is also a cause, and some patients are anti-phospholipase A2 receptor antibody positive." },
  { id: "rp33", category: "Glomerular", q: "Hepatitis C plus nephritic syndrome vs hepatitis B plus nephrotic syndrome?", a: "HepC plus nephritic -> MPGN. HepB plus nephrotic -> membranous glomerulonephropathy." },
  { id: "rp34", category: "Glomerular", q: "Multiple myeloma plus a renal diagnosis?", a: "Renal amyloidosis. Light chains in high volume moving through the kidney (Bence Jones proteinuria) deposit in the parenchyma. Memorize: multiple myeloma is the most common cause of renal amyloidosis." },
  // ===== RENAL: Diabetic Kidney =====
  { id: "rp35", category: "Diabetic Kidney", q: "First change in the kidney in diabetes - overall vs histologic?", a: "Overall first change: hyperfiltration (filtered glucose pulls water with it). First HISTOLOGIC change: thickening of the glomerular basement membrane from non-enzymatic glycosylation. If asked for the first renal change overall, pick hyperfiltration." },
  { id: "rp36", category: "Diabetic Kidney", q: "A diabetic man has polyuria. Why is urinary output increased?", a: "Increased glomerular filtration rate. That is the NBME answer." },
  { id: "rp37", category: "Diabetic Kidney", q: "How much filtered glucose does the PCT reabsorb, and when does glycosuria start?", a: "100% physiologically. Glycosuria is not seen until serum glucose exceeds roughly 180 mg/dL." },
  { id: "rp38", category: "Diabetic Kidney", q: "Late histologic finding in diabetic nephropathy, and what is it made of?", a: "Kimmelstiel-Wilson nodules, composed of HYALINE. Do not confuse with the FIBRIN crescents of RPGN." },
  { id: "rp39", category: "Diabetic Kidney", q: "What is hyaline arteriolosclerosis?", a: "Hyaline deposition in renal arterioles, usually in diabetes. Non-enzymatic glycosylation of vascular endothelium -> leakage of plasma proteins into vessel walls." },
  { id: "rp40", category: "Diabetic Kidney", q: "First drug for a diabetic with hypertension or proteinuria, and the most common cause of chronic renal failure?", a: "ACE inhibitor (enalapril) or ARB (valsartan). Most common cause of chronic renal failure is diabetes mellitus." },
  { id: "rp41", category: "Renal Pharm", q: "Which type 2 diabetes drug acts in the kidney, and where?", a: "Dapagliflozin - SGLT2 inhibitor in the PCT, preventing glucose reabsorption." },
  // ===== RENAL: Hemodynamics + RAAS =====
  { id: "rp42", category: "Renal Physiology", q: "Which endogenous mediators control the afferent vs efferent arteriole?", a: "Prostaglandins DILATE the afferent. Angiotensin-II CONSTRICTS the efferent." },
  { id: "rp43", category: "Renal Physiology", q: "What do NSAIDs and ACEi/ARBs do to renal vasculature - precisely?", a: "NSAIDs decrease DILATION of the afferent arteriole (less prostaglandin, not active constriction). ACEi/ARBs decrease CONSTRICTION of the efferent arteriole (less AT-II, not active dilation). USMLE shows a glomerulus picture and asks where each drug acts." },
  { id: "rp44", category: "Renal Physiology", q: "Why does AT-II act on the efferent arteriole physiologically, and what do ACEi/ARBs do to filtration fraction?", a: "Low blood volume -> increased AT-II -> efferent constriction -> increased filtration fraction (GFR/RBF) -> GFR is maintained despite reduced renal blood flow. ACEi/ARBs DECREASE filtration fraction." },
  { id: "rp45", category: "Renal Physiology", q: "If ACEi/ARBs decrease filtration fraction, why give them first-line in diabetic kidney disease?", a: "Paradoxical but correct: you also decrease the rate glucose is filtered across the basement membrane, slowing non-enzymatic glycosylation and disease progression. Early on they are mainstay; patients with end-stage renal disease are generally taken off them." },
  { id: "rp46", category: "Renal Physiology", q: "Explain the RAAS pathway end to end.", a: "Reduced renal perfusion (low volume, renal artery stenosis, fibromuscular dysplasia) -> juxtaglomerular cells secrete renin -> renin cleaves liver-made angiotensinogen to AT-I -> ACE in the LUNG cleaves AT-I to AT-II -> AT-II constricts systemic arterioles and the efferent arteriole, and upregulates aldosterone synthase in the zona glomerulosa (11-deoxycorticosterone -> aldosterone)." },
  { id: "rp47", category: "Renal Physiology", q: "Where does aldosterone act and by what mechanism?", a: "Cortical collecting duct. Binds an intracytosolic receptor -> upregulates basolateral Na/K-ATPase (3 Na reabsorbed into blood, 2 K into the cell per ATP) -> lowers intracellular Na -> favorable gradient from urine into cell -> ENaC upregulated on the apical membrane. Net: increased Na reabsorption, increased K secretion." },
  { id: "rp48", category: "Renal Physiology", q: "What autonomic activity causes renin release?", a: "Beta-1 activity. If a patient has low blood volume and they ask what is true, the answer is 'increased renal sympathetic activity.'" },
  { id: "rp49", category: "Renal Physiology", q: "What are the JGA and macula densa, and how do they sense volume?", a: "The juxtaglomerular apparatus contains JG cells that secrete renin. The macula densa is modified smooth muscle of the DCT that senses tubular sodium. Low volume -> PCT reabsorbs more Na and water -> less Na reaching the distal nephron -> macula densa reads that as volume deficit -> triggers renin secretion." },
  { id: "rp50", category: "Water Balance", q: "Where does vasopressin (ADH) act and what does it do?", a: "Medullary collecting duct. Inserts aquaporins on the apical membrane -> increased free water reabsorption." },
  { id: "rp51", category: "Water Balance", q: "Urine and serum findings: SIADH vs diabetes insipidus vs psychogenic polydipsia?", a: "SIADH: concentrated urine (high osmolality), LOW serum Na (<135). DI: dilute urine, HIGH serum Na (>145). Psychogenic polydipsia: dilute urine, LOW serum Na (<135)." },
  { id: "rp52", category: "Water Balance", q: "Which drugs cause nephrogenic diabetes insipidus?", a: "Lithium and demeclocycline." },
  { id: "rp53", category: "Water Balance", q: "In DI, is the fluid hypotonic, isotonic, or hypertonic at the PCT, JGA, and medullary collecting duct?", a: "PCT is ALWAYS isotonic regardless of renal condition. JGA is ALWAYS hypotonic regardless of condition. Medullary collecting duct is hypotonic in DI - in SIADH that last one would instead be hypertonic." },
  { id: "rp54", category: "Renal Pharm", q: "Tolvaptan and conivaptan - what are they and when are they used?", a: "Vasopressin (ADH) receptor antagonists, used in SIADH - for example SIADH from small cell lung cancer." },
  // ===== RENAL: Acute Renal Failure =====
  { id: "rp55", category: "Acute Renal Failure", q: "BUN/Cr ratio in pre-renal vs intra-renal vs post-renal failure?", a: "Greater than 20 = pre-renal. Less than 20 = not pre-renal. Per Mehlman, ignore FA's <15 intra- / 15-20 post- split: he has seen at least three 2CK NBME/CMS questions where the diagnosis was ATN with a BUN/Cr in the 16s or 17s. Just know >20 = pre-renal." },
  { id: "rp56", category: "Acute Renal Failure", q: "FeNa and urine osmolality in pre-renal vs intra-/post-renal failure?", a: "FeNa <1% in pre-renal, >1% in intra-/post-renal. Urine osmolality concentrated (>500 mOsm) in pre-renal, dilute (<350 mOsm) in intra-/post-. The low FeNa is the PCT avidly reabsorbing Na in a low-volume state (water follows sodium)." },
  { id: "rp57", category: "Acute Renal Failure", q: "When is pre-renal failure the answer apart from BUN/Cr >20?", a: "CHF classically (decreased renal perfusion), hypovolemia generally when not acute, and contrast nephropathy. Note: if the vignette gives ACUTE hypovolemia with no BUN or Cr mentioned, the answer is acute tubular necrosis, not pre-renal. NBME may phrase the etiology as 'decreased glomerular filtration.'" },
  { id: "rp58", category: "Acute Renal Failure", q: "Contrast agents cause which type of renal failure, and what prevents it?", a: "Either - pre-renal via afferent arteriolar spasm, or intra-renal via direct nephrotoxicity. Always give fluids to prevent. High-yield." },
  { id: "rp59", category: "Acute Renal Failure", q: "A man has an MI and low blood pressure. Which renal handling change is most likely seen?", a: "Increased potassium secretion. Low-volume status -> RAAS upregulation -> distal K wasting. That is the NBME answer." },
  { id: "rp60", category: "Acute Renal Failure", q: "When is intra-renal failure the answer, and what are the classic triggers?", a: "Acute tubular necrosis from hypoxia at the kidney: major blood loss (intra-operative, exsanguination) or arrhythmia (VF, resuscitated). The vignette gives acute oliguria with or without dark urine - they do NOT have to mention BUN, Cr, or muddy brown casts. Other intra-renal causes: gentamicin, rhabdomyolysis (myoglobin), contrast nephropathy." },
  { id: "rp61", category: "Acute Renal Failure", q: "Why does acute hypoxia hit the proximal tubule specifically?", a: "The PCT is loaded with transporters, especially Na/K-ATPases, so it has high oxygen demand. Same reason diffuse cortical necrosis is classically associated with obstetric catastrophes. A lab animal given 100% nitrogen infarcts the PROXIMAL TUBULE." },
  { id: "rp62", category: "Acute Renal Failure", q: "A man has an MI requiring resuscitation and then becomes oliguric. What do you see on microscopy of the kidney?", a: "'Degenerating epithelial cells and dirty brown granular casts,' or 'necrosis of epithelial cells in proximal convoluted tubules.' Both are NBME phrasings for ATN." },
  { id: "rp63", category: "Acute Renal Failure", q: "Electrolyte course in ATN?", a: "Week 1 is the oliguric phase: HYPERkalemia from decreased filtration. Weeks 2-3 are the polyuric phase: HYPOkalemia from kaliuresis, because PCT cells cannot reabsorb K yet." },
  { id: "rp64", category: "Acute Renal Failure", q: "When is post-renal failure the answer, and how does the USMLE assess it?", a: "BPH classically, or distal obstruction from strictures or malignancy. They show hydronephrosis with BPH and ask the cause of the picture: 'increased Bowman capsule hydrostatic pressure' or 'increased tubular hydrostatic pressure.' That answer is on several NBMEs." },
  { id: "rp65", category: "Urinalysis + Casts", q: "Match the cast: hyaline, waxy, RBC, WBC, muddy brown granular.", a: "Hyaline -> dehydration. Waxy -> end-stage renal disease. RBC -> glomerulonephritis. WBC -> pyelonephritis. Muddy brown granular -> ATN. Careful: plain 'granular casts' are not specific to ATN - an IM CMS question with CVA tenderness plus granular casts is pyelonephritis." },
  { id: "rp66", category: "Urinalysis + Casts", q: "What is Tamm-Horsfall protein?", a: "The most common protein found in urine, not found in plasma, produced by tubular cells (classically thick ascending limb). No other real significance - it just pops up in Qbank." },
  { id: "rp67", category: "Urinalysis + Casts", q: "An 82-year-old woman falls down the stairs; dipstick shows 2+ blood but only 3-4 RBCs/hpf on microscopy. Diagnosis?", a: "Rhabdomyolysis. A false-positive dipstick for blood is rhabdo - the dipstick cannot differentiate myoglobinuria from actual RBCs." },
  // ===== RENAL: Tubulointerstitial + Analgesic =====
  { id: "rp68", category: "Tubulointerstitial", q: "What is interstitial nephritis and what causes it?", a: "Tubulointerstitial nephritis - WBCs (eosinophils) in the urine, with or without a fine maculopapular rash. Almost always beta-lactams or cephalosporins; NSAIDs can also do it (a form of analgesic nephropathy)." },
  { id: "rp69", category: "Tubulointerstitial", q: "A 62-year-old man on 6 weeks of nafcillin for MSSA endocarditis now has WBCs on urinalysis. Diagnosis?", a: "Interstitial nephritis. Beta-lactam is the classic trigger." },
  { id: "rp70", category: "Tubulointerstitial", q: "A 35-year-old woman uses ibuprofen daily for headaches and has a rash plus eosinophils in the urine. What is on biopsy?", a: "'Inflammatory infiltrates in the interstitium' - the NBME phrasing for interstitial nephritis." },
  { id: "rp71", category: "Tubulointerstitial", q: "What is analgesic nephropathy and its three faces?", a: "Renal damage from NSAIDs: renal papillary necrosis (dark urine from ischemia), interstitial nephritis (eosinophils in urine, rash not required), or generalized edema from reduced renal blood flow." },
  { id: "rp72", category: "Tubulointerstitial", q: "An 80-year-old woman on high-dose naproxen for 6 weeks develops peripheral edema. Mechanism?", a: "'Increased renal retention of sodium' (or 'decreased renal excretion of sodium'). NSAID knocks out COX -> decreased prostaglandins -> decreased afferent arteriolar dilation -> decreased renal blood flow -> PCT senses low volume and increases Na reabsorption -> water follows sodium -> edema. Per Mehlman the USMLE has an obsession with naproxen; OA should be treated with acetaminophen before NSAIDs." },
  { id: "rp73", category: "Tubulointerstitial", q: "In analgesic nephropathy, if the question asks about arteriolar effect specifically, what is the answer?", a: "The NSAID inhibits 'vasodilating prostaglandins at the afferent arteriole.'" },
  { id: "rp74", category: "Tubulointerstitial", q: "When is renal papillary necrosis the answer?", a: "Sickle cell classically; also NSAIDs. Urine is dark. The renal papillae in the medulla get the least blood flow, so small microvascular changes cause sloughing and necrosis. Contrast with diffuse cortical necrosis and ATN, which follow massive acute ischemic events." },
  // ===== RENAL: Stones =====
  { id: "rp75", category: "Stones", q: "First answer for treatment of ALL kidney stones on the USMLE?", a: "Hydration / fluids." },
  { id: "rp76", category: "Stones", q: "Treatment and prevention: calcium oxalate vs calcium phosphate stones?", a: "Both: fluids, then thiazide to prevent recurrence (decreases urinary Ca). Calcium OXALATE: also alkalinize the urine with citrate. Calcium PHOSPHATE: do NOT alkalinize - phosphate stones form at higher pH, oxalate stones at lower pH, which is why citrate helps oxalate only." },
  { id: "rp77", category: "Stones", q: "Treatment of struvite stones?", a: "Fluids, acidify the urine with ammonium chloride, and surgery - they are often huge (staghorn)." },
  { id: "rp78", category: "Stones", q: "Treatment of uric acid stones?", a: "Fluids plus alkalinize the urine with citrate; treat the underlying gout; avoid uricosurics like probenecid indefinitely; avoid low-dose aspirin." },
  { id: "rp79", category: "Stones", q: "Treatment of cystine stones?", a: "Fluids and alkalinize the urine with citrate." },
  { id: "rp80", category: "Stones", q: "Who gets calcium oxalate stones and why?", a: "Intestinal malabsorption - Crohn, celiac, CF. Fat malabsorption -> fat binds calcium in the gut -> less calcium available to bind oxalate -> more oxalate absorbed. Also ethylene glycol (antifreeze) poisoning and hypervitaminosis C." },
  { id: "rp81", category: "Stones", q: "Who gets struvite stones and what do they look like?", a: "UTIs with urease-positive organisms - Proteus is classic. Coffin lid-shaped crystals." },
  { id: "rp82", category: "Stones", q: "Who gets uric acid stones, and how do they appear on CT?", a: "Uric acid overproducers - Lesch-Nyhan, tumor lysis syndrome - and alcoholics (USMLE wants UNDER-excretion as the mechanism by which ethanol causes gout, though it also increases production). Stones are RADIOLUCENT on non-contrast CT." },
  { id: "rp83", category: "Stones", q: "Who gets cystine stones, and what are the testable factoids?", a: "Cystinuria - inability to reabsorb COLA (cysteine, ornithine, lysine, arginine). Two cysteines joined by a disulfide bond make one cystine. Autosomal recessive, young adults, nitroprusside urine test turns magenta, hexagon-shaped stones." },
  // ===== RENAL: Renal Tubular Acidosis =====
  { id: "rp84", category: "Acid-Base", q: "RTA type I - defect, urine pH, potassium, associations?", a: "Decreased ability of the DCT to secrete protons. Urine pH >5.5. Metabolic acidosis WITHOUT hyperkalemia. Associated with bilateral renal parenchymal stones (in the meat of the kidney, not the lumina) and Sjogren syndrome." },
  { id: "rp85", category: "Acid-Base", q: "RTA type II - defect, urine pH, potassium, associations?", a: "Decreased PCT bicarbonate reabsorption. Urine pH >5.5. No hyperkalemia. Associated with carbonic anhydrase inhibitors and Fanconi syndrome (expired tetracyclines)." },
  { id: "rp86", category: "Acid-Base", q: "RTA type IV - defect, urine pH, potassium, and the classic vignette?", a: "Hyporeninemic hypoaldosteronism or aldosterone insensitivity at the kidney. Urine pH <5.5. HYPERkalemic, unlike RTA I and II. Classic: a 68-year-old diabetic with biochemistry resembling Addison disease - low Na, high K, low bicarb - but the etiology is chronic renal failure, not adrenal." },
  { id: "rp87", category: "Acid-Base", q: "In Fanconi syndrome, what happens to absorption of glucose, amino acids, phosphate, and bicarbonate?", a: "Decreased absorption for all four. That is the NBME answer." },
  // ===== RENAL: Diuretics =====
  { id: "rp88", category: "Renal Pharm", q: "Mannitol - mechanism, site, uses, and the one contraindication?", a: "Osmotic diuretic that retains water in the nephron lumen. USMLE wants the PROXIMAL STRAIGHT TUBULE if it is drawn and labeled; if not shown, choose the thin descending limb over the PCT. Used for increased intracranial pressure after intubation and hyperventilation. Avoid in heart failure - it transiently increases intravascular volume -> increased preload -> increased myocardial oxygen demand." },
  { id: "rp89", category: "Renal Pharm", q: "Acetazolamide at the kidney - mechanism and classic use?", a: "Carbonic anhydrase inhibitor preventing bicarbonate reabsorption -> transient metabolic acidosis, which counteracts the respiratory alkalosis of altitude sickness (the kidney cannot compensate fast enough on its own, so the drug forces it)." },
  { id: "rp90", category: "Renal Pharm", q: "Everything high-yield about loop diuretics?", a: "Furosemide is first-line. Inhibits the Na/K/2Cl symporter on the apical membrane of the thick ascending limb. Does NOT decrease mortality in heart failure - symptom relief only. Causes hypokalemia and contraction alkalosis (RAAS kicks up and secretes protons distally), plus INCREASED urinary calcium and magnesium. Ototoxic, especially with aminoglycosides. Furosemide is a sulfa drug - use ethacrynic acid in sulfa allergy (memorize that). Bumetanide is an alternative. Loops are the most effective fluid-unloaders of all diuretics." },
  { id: "rp91", category: "Renal Physiology", q: "How are calcium and magnesium reabsorbed in the thick ascending limb?", a: "Paracellularly - between the cells." },
  { id: "rp92", category: "Renal Pharm", q: "Everything high-yield about thiazides?", a: "HCTZ inhibits the Na/Cl symporter on the apical membrane of the early DCT. DECREASED urinary calcium and magnesium (opposite of loops). Causes hyperGLUC - hyperglycemia, hyperlipidemia, hyperuricemia, hypercalcemia - so avoid in diabetics and gout. Can prevent recurrent calcium stones. Used for HTN in patients WITHOUT cardiovascular disease or diabetes (those get ACEi/ARB first). Chlorthalidone is an alternative." },
  { id: "rp93", category: "Renal Physiology", q: "Bartter vs Gitelman syndrome?", a: "Bartter behaves as if the patient is permanently on a LOOP diuretic (associated with JG cell hyperplasia). Gitelman behaves as if permanently on a THIAZIDE." },
  { id: "rp94", category: "Renal Pharm", q: "Amiloride and triamterene - mechanism?", a: "ENaC inhibitors, potassium-sparing (no kaliuresis)." },
  { id: "rp95", category: "Renal Pharm", q: "Spironolactone - mechanism, uses, and side effect?", a: "Aldosterone receptor antagonist. Used in heart failure once the patient is on an ACEi/ARB plus beta-blocker, and in Conn syndrome. USMLE loves it as the add-on for a patient already on furosemide - the loop unloads best but wastes K, spironolactone is K-sparing. Causes gynecomastia (anti-androgenic); eplerenone is the alternative with much less gynecomastia. These DO decrease mortality in heart failure, in contrast to furosemide." },
  { id: "rp96", category: "Acid-Base", q: "A patient on chronic furosemide has pH 7.52, HCO3 34, urine Cl <10. What is the disturbance and why is urine chloride low?", a: "Contraction alkalosis - saline-responsive metabolic alkalosis. Volume depletion drives avid Na and Cl reabsorption, so urine Cl is low. Per Mehlman: urine Cl <20 = saline-responsive (vomiting, diuretics, contraction); >20 = saline-resistant (Conn, Bartter, Gitelman). Treat with normal saline." },
  // ===== RENAL: Calcium, PTH, Bone =====
  { id: "rp97", category: "Calcium + Bone", q: "Three main effects of PTH at the kidney?", a: "1) Upregulates the apical Ca/PO4 antiporter in the late DCT - increases Ca reabsorption and phosphate secretion. 2) Decreases phosphate reabsorption in the PCT. 3) Upregulates 1-alpha-hydroxylase in the PCT -> 25-OH-D3 converted to active 1,25-(OH)2-D3 -> increased gut Ca and PO4 absorption plus mineralization of osteoid into hydroxyapatite." },
  { id: "rp98", category: "Calcium + Bone", q: "What PTH pathology is seen in chronic renal failure, and what are the arrows?", a: "Secondary hyperparathyroidism. Kidney cannot excrete PO4 or reabsorb Ca -> DECREASED serum Ca, INCREASED serum PO4 -> increased PTH." },
  { id: "rp99", category: "Calcium + Bone", q: "Vitamin D forms in renal disease, and why are the electrolytes not those of simple vitamin D deficiency?", a: "Decreased 1,25-(OH)2-D3 and increased 24,25-(OH)2-D3 (inactive storage form; NBME asks about 24,25). Vitamin D deficiency alone gives low Ca AND low PO4, but in chronic renal failure the renal disease always wins: decreased filtration of phosphate beats decreased gut absorption, so PO4 is HIGH with Ca LOW." },
  { id: "rp100", category: "Calcium + Bone", q: "What is renal osteodystrophy, and what does a pseudofracture of the hip in chronic renal disease mean?", a: "Renal osteodystrophy is any bone problem caused by renal disease (PTH or vitamin D related). A pseudofracture is pathognomonic for vitamin D deficiency -> osteomalacia, here as a form of renal osteodystrophy." },
  { id: "rp101", category: "Chronic Renal Failure", q: "Renal failure plus a friction rub on chest auscultation. Diagnosis and treatment?", a: "Uremic pericarditis, a fibrinous pericarditis. USMLE treatment is immediate hemodialysis." },
  { id: "rp102", category: "Chronic Renal Failure", q: "Full biochemical picture of renal disease?", a: "Sodium variable; potassium HIGH; calcium LOW; phosphate HIGH; bicarb LOW; pH LOW; CO2 LOW (respiratory compensation)." },
  { id: "rp103", category: "Chronic Renal Failure", q: "EPO and the kidney - high vs low in which conditions?", a: "The kidney secretes EPO in response to hypoxemia. HIGH EPO in lung disease (secondary polycythemia) and often in renal cell carcinoma. LOW EPO in polycythemia vera (JAK2 mutation drives marrow overproduction, so EPO is suppressed)." },
  // ===== RENAL: Tumors + Cystic Disease =====
  { id: "rp104", category: "Renal Masses", q: "A smoker has hypercalcemia and polycythemia - and separately, a smoker has flank pain and red urine. Diagnosis?", a: "Renal cell carcinoma both times. Paraneoplastic EPO and PTHrP explain the first; flank pain plus hematuria is the classic second." },
  { id: "rp105", category: "Renal Masses", q: "Most common type of RCC, and the syndrome to know?", a: "Clear cell carcinoma (large clear cells on histology). Von Hippel-Lindau - autosomal dominant, chromosome 3, bilateral RCC, retinal and cerebellar hemangioblastomas, caused by constitutive activation of hypoxia-inducible factor." },
  { id: "rp106", category: "Renal Masses", q: "A 3-year-old boy has a painless flank mass and nothing else. Diagnosis?", a: "Wilms tumor - the renal cancer of children." },
  { id: "rp107", category: "Renal Masses", q: "A 6-year-old boy has a painless flank mass, seizure, and periventricular nodules on brain MRI. Diagnosis?", a: "Tuberous sclerosis with renal angiomyolipoma." },
  { id: "rp108", category: "Renal Masses", q: "Horseshoe kidney - two testable points?", a: "Increased risk of Wilms tumor (and it is associated with Turner syndrome), and the kidney gets caught under the inferior mesenteric artery. Step 1 loves the IMA factoid." },
  { id: "rp109", category: "Renal Masses", q: "WAGR, Denys-Drash, and Beckwith-Wiedemann - define each and the gene.", a: "WAGR: Wilms, Aniridia, Genitourinary malformation, Retardation - WT1. Denys-Drash: Wilms plus male pseudohermaphroditism - WT1. Beckwith-Wiedemann: Wilms plus neonatal hypoglycemia, macrosomia/macroglossia, hemihypertrophy, with or without omphalocele - WT2." },
  { id: "rp110", category: "Cystic Renal Disease", q: "ARPKD vs ADPKD?", a: "ARPKD: chromosome 6, pediatric, associated with hepatic fibrosis. ADPKD: chromosome 16, presents in the 30s-40s, associated with hypertension and circle of Willis berry aneurysms. Most common extra-renal cyst location is the LIVER." },
  { id: "rp111", category: "Cystic Renal Disease", q: "In ADPKD management, which matters more - serial BP checks or MR angiogram of the circle of Willis?", a: "Serial BP checks. Renal cysts compress microvasculature -> surges in RAAS." },
  { id: "rp112", category: "Renal Vascular", q: "Comment on systemic sclerosis and the kidney.", a: "Diffuse systemic sclerosis can cause renal crisis with malignant hypertension." },
  { id: "rp113", category: "Renal Vascular", q: "A 68-year-old diabetic with intermittent claudication and prior CABG has gradually rising BP over two years. Diagnosis and cause?", a: "Renal artery stenosis, caused by atherosclerosis. They will always give RAS in a patient with cardiovascular disease." },
  { id: "rp114", category: "Renal Vascular", q: "A 23-year-old woman has high aldosterone, high renin, and high BP. Diagnosis and how do you diagnose it?", a: "Fibromuscular dysplasia - NOT renal artery stenosis (RAS means atherosclerosis). FMD is a tunica media proliferative pathology in young women. Diagnose with MR angiography; NBME has used 'string of beads.'" },
  { id: "rp115", category: "Renal Vascular", q: "A hypertensive patient is given an ACEi or ARB and spikes renin or creatinine. Diagnosis and why?", a: "FMD if young, RAS if the patient has cardiovascular disease. Renal blood flow is already reduced, so the kidney has little reserve to hold GFR; the ACEi/ARB drops filtration fraction -> clinically significant GFR fall -> renin and Cr rise. Shows up on Steps 1 and 2CK." },
  // ===== RENAL: Lower Urinary Tract =====
  { id: "rp116", category: "Incontinence", q: "Many pregnancies plus downward movement of the vesicourethral junction. Type of incontinence and treatment?", a: "Stress incontinence. Treat with pelvic floor (Kegel) exercises; if insufficient, mid-urethral sling." },
  { id: "rp117", category: "Incontinence", q: "Hyperactive detrusor, needing to run to the bathroom when putting the key in the door, incontinence in MS or perimenopause. Type and treatment?", a: "Urge incontinence. Treat with oxybutynin (muscarinic antagonist) or mirabegron (beta-3 agonist)." },
  { id: "rp118", category: "Incontinence", q: "Incontinence with a post-void residual of 300-400 mL (normal <50). Type, and the two classic settings?", a: "Overflow incontinence. Diabetes (neurogenic bladder) and BPH (outlet obstruction -> eventual neurogenic bladder)." },
  { id: "rp119", category: "Incontinence", q: "Treatment of overflow incontinence in diabetes vs in BPH?", a: "Diabetes: bethanechol (muscarinic agonist). BPH: insert a catheter first, then alpha-1 blocker and/or 5-alpha-reductase inhibitor, then TURP if necessary." },
  { id: "rp120", category: "Urology", q: "Innervation of the external urethral sphincter, internal urethral sphincter, and detrusor?", a: "External urethral sphincter: pudendal nerve (somatic, voluntary). Internal urethral sphincter: hypogastric nerves (sympathetic). Detrusor: pelvic splanchnic nerves (parasympathetic, S2-4)." },
  { id: "rp121", category: "Urology", q: "BPH treatment, and treatment of prostatic adenocarcinoma?", a: "BPH: alpha-1 blocker (tamsulosin, terazosin) and/or 5-alpha-reductase inhibitor (finasteride); mono- or dual therapy. Prostate cancer: flutamide plus leuprolide together - flutamide blocks androgen receptors, leuprolide is a GnRH agonist that shuts off LH/FSH when given continuously. If forced to sequence, flutamide first." },
  { id: "rp122", category: "Urology", q: "Exquisitely tender prostate on digital rectal exam. Diagnosis and treatment?", a: "Prostatitis. Treat with ciprofloxacin (fluoroquinolone - DNA gyrase / topoisomerase II inhibitor)." },
  { id: "rp123", category: "Urology", q: "What is a Brenner tumor?", a: "An ovarian tumor with bladder (transitional cell) epithelium." },
  { id: "rp124", category: "Urology", q: "What is 'water under the bridge,' and which vessel injures the ureter during oophorectomy?", a: "The ureter travels UNDER the uterine artery in women and the vas deferens in men. During oophorectomy, ureteric damage occurs during ligation of the OVARIAN artery." },
  // ===== RENAL: Infection =====
  { id: "rp125", category: "Renal Infection", q: "Costovertebral angle tenderness plus fever - and CVA tenderness plus granular casts. Diagnosis?", a: "Pyelonephritis both times. The granular casts version is on a 2CK NBME and is NOT acute tubular necrosis, weird as that sounds. Treat with ciprofloxacin, or ampicillin plus gentamicin." },
  { id: "rp126", category: "Renal Infection", q: "When is chronic pyelonephritis the answer, and what do they show?", a: "A young child (3-4) with recurrent acute pyelo - recurrent acute pyelo is what causes chronic pyelo. Step 1 shows a small scarred kidney and wants 'vesicoureteral reflux' as the mechanism; biopsy shows 'tubular atrophy'; ultrasound shows broad scars with blunted calyces. 'Thyroidization of the kidney' is Qbank buzz, not NBME." },
  { id: "rp127", category: "Renal Infection", q: "Treatment for a simple UTI?", a: "Nitrofurantoin is the classic answer (including in pregnancy - it is listed as correct on many 2CK-level NBME/CMS questions); TMP/SMX is the other classic." },
  { id: "rp128", category: "Renal Infection", q: "Best initial management to prevent recurrent UTIs, and the escalation?", a: "Postcoital voiding first. If unsuccessful, 'postcoital nitrofurantoin prophylaxis'; if that is not listed, 'daily TMP/SMX prophylaxis' - which sounds outrageous but is correct on an obgyn CMS form." },
  { id: "rp129", category: "Renal Infection", q: "Asymptomatic bacteriuria - treat or not, and why?", a: "Treat if pregnant; do not treat if not pregnant. Exceedingly high-yield for 2CK. In pregnancy, progesterone slows ureteric peristalsis, raising the risk of pyelonephritis." },
  { id: "rp130", category: "Renal Infection", q: "A 22-year-old woman has 6 months of dysuria, anterior vaginal wall pain, a completely normal urinalysis, and no fever. Diagnosis?", a: "Chronic interstitial cystitis - at least 6 weeks of UTI-like symptoms with no identifiable pathology. Answer on an obgyn form." },
  { id: "rp131", category: "Renal Infection", q: "A 22-year-old woman has UTI symptoms with a completely normal urinalysis. Next best step?", a: "Test for chlamydia and gonorrhea. Answer on one of the newer obgyn forms." },
  { id: "rp132", category: "Renal Infection", q: "A 25-year-old man has mucopurulent urethral discharge and culture grows nothing. Diagnosis and treatment?", a: "Chlamydia (obligate intracellular, so it will not grow). On the Step, ALWAYS cotreat: IM ceftriaxone plus either oral azithromycin or oral doxycycline. Every NBME/CMS question has cotreatment as the answer; if ceftriaxone is not listed, pick the combo containing a cephalosporin." },
  { id: "rp133", category: "Renal Infection", q: "Endocarditis after a genitourinary procedure such as TURP, or after catheterization. Organism?", a: "Enterococcus." },
  { id: "rp134", category: "Bladder Cancer", q: "Most common type of bladder cancer, most common cause, most specific cause, and the Schistosoma variant?", a: "Most common type: transitional cell carcinoma. Most common cause: smoking. Most specific cause: industrial (aniline) dyes. Schistosoma haematobium -> squamous cell carcinoma." },
  // ===== RENAL: Peds, Congenital, Trauma =====
  { id: "rp135", category: "Congenital Renal", q: "A 27-year-old man has a dilated renal pelvis and collecting system but non-dilated ureters. Diagnosis?", a: "Incomplete recanalization of the proximal ureter - that is the exact phrasing USMLE wants." },
  { id: "rp136", category: "Congenital Renal", q: "What is Potter sequence?", a: "Renal agenesis -> oligohydramnios -> pulmonary hypoplasia in the fetus." },
  { id: "rp137", category: "Congenital Renal", q: "Most common genitourinary abnormality in neonatal males, its presentation, and workup?", a: "Posterior urethral valves - thin membranes in the urethra blocking urine outflow. Male neonate with a suprapubic mass and no passage of urine. Next step: voiding cystourethrogram. Treatment is surgery." },
  { id: "rp138", category: "Renal Trauma", q: "A 34-year-old man falls on a balance beam with a saddle injury and has blood at the urethral meatus. Diagnosis and next step?", a: "Urethral injury -> retrograde urethrogram." },
  { id: "rp139", category: "Renal Trauma", q: "A 16-year-old has a skiing accident with flank bruising/pain and GROSS hematuria. Next best step?", a: "CT with contrast - not ultrasound. Exceedingly high-yield on surgery forms, even though contrast is nephrotoxic. Do not pick ultrasound." },
  { id: "rp140", category: "Renal Trauma", q: "Same skiing accident with flank pain but the urine is NOT red. Next best step, and then what?", a: "Urinalysis to look for blood (super high-yield). If the U/A shows blood, get the CT. If the U/A is normal, 'no further investigations indicated.'" },
  { id: "rp141", category: "Renal Physiology", q: "A 65-year-old man had a creatinine of 1.0 mg/dL and 10 years later it is 1.2 mg/dL. Diagnosis?", a: "Normal aging - creatinine clearance naturally falls with age. Know that a Cr of 1.5 or greater is always pathologic, and at Cr 2.0 more than 90% of nephron function has been lost." },
  { id: "rp142", category: "Renal Vascular", q: "A child has bloody diarrhea, petechiae, and red urine. Diagnosis and mechanism?", a: "Hemolytic uremic syndrome from EHEC O157:H7 or Shigella. Triad: thrombocytopenia, schistocytes (microangiopathic hemolytic anemia), renal insufficiency. Toxin inhibits ADAMTS13 in afferent arterioles plus endothelial damage -> platelet consumption and clumping -> RBCs shear passing the clumps." },
  { id: "rp143", category: "Renal Vascular", q: "How does TTP contrast with HUS?", a: "TTP is not toxin-induced: it is a mutation in ADAMTS13 or antibodies against it -> cannot cleave vWF multimers -> platelet clumping. TTP is a PENTAD - the HUS findings plus fever and neurologic signs." },
  { id: "rp144", category: "Chronic Renal Failure", q: "What is hepatorenal syndrome, and what does the USMLE want on biopsy?", a: "Liver failure causing renal failure. The answer USMLE wants is a NORMAL renal biopsy, though recent literature describes 'glomerular tubular reflux.'" },
  // ===== PULM: Pulmonary Hypertension + Cor Pulmonale =====
  { id: "rp145", category: "Pulmonary HTN", q: "A 58-year-old woman has 6 months of dyspnea and dry cough, 2 years of worsening dysphagia, and 20 years of hands turning white in the cold. What lung condition is she most at risk of?", a: "Pulmonary hypertension. Pulmonary fibrosis is common in CREST / limited systemic sclerosis (fibrosis occurs in both diffuse and limited types) -> pulmonary HTN -> can progress to cor pulmonale." },
  { id: "rp146", category: "Pulmonary HTN", q: "What vignette descriptors hint at pulmonary hypertension?", a: "Loud S2 or P2 (the pulmonic valve slams shut when distal pressure is high), dilation of the proximal pulmonary arteries, and increased pulmonary vascular markings." },
  { id: "rp147", category: "Pulmonary HTN", q: "In Eisenmenger syndrome, what is the most upstream cause of shunt reversal?", a: "The pulmonary hypertension, NOT the RVH. Chronic increased pulmonary flow -> tunica media hypertrophy of pulmonary arterioles -> backup of hydrostatic pressure -> increased right heart afterload -> RVH -> shunt reverses right to left." },
  { id: "rp148", category: "Pulmonary HTN", q: "Define cor pulmonale and the two things that must be true in the vignette.", a: "Right heart failure secondary to a pathology of pulmonary etiology - the LEFT heart must not be the cause (the most common cause of right heart failure overall is left heart failure). Right heart failure signs must actually be present (JVD, edema, hepatosplenomegaly); pulmonary HTN findings alone are not enough. PCWP must be NORMAL in cor pulmonale." },
  { id: "rp149", category: "Pulmonary HTN", q: "Walk the mechanism of cor pulmonale in COPD or CF.", a: "Inadequate alveolar ventilation -> hypoxic vasoconstriction of pulmonary vessels -> increased afterload in the proximal pulmonary arteries -> dilation and congestion -> more hydrostatic pressure -> right heart hypertrophies -> right heart decompensates -> JVD, edema, hepatosplenomegaly. The degree of hypoxic vasoconstriction determines prognosis. In fibrosis (CREST, prior chest radiation) the pulmonary HTN need not be from hypoxic vasoconstriction." },
  { id: "rp150", category: "Hemodynamics", q: "Explain PCWP and what it equals.", a: "A catheter fed through the venous circulation into a distal pulmonary arteriole senses the pulmonary capillary pressure, which reflects left atrial pressure because the left atrium is immediately contiguous. So PCWP = left atrial pressure. Memorize it." },
  { id: "rp151", category: "Hemodynamics", q: "Shock arrows: hypovolemic, cardiogenic, septic/anaphylactic, neurogenic/adrenal crisis. Give CO, VR, TPR, PCWP.", a: "Hypovolemic: CO down, VR down, TPR UP, PCWP down. Cardiogenic: CO down, VR down, TPR UP, PCWP UP. Septic and anaphylactic: CO UP, VR UP, TPR down, PCWP normal. Neurogenic and adrenal crisis: CO down, VR down, TPR down, PCWP normal. Post-MI plus low BP plus high PCWP -> cardiogenic shock." },
  { id: "rp152", category: "Pulmonary HTN", q: "A 23-year-old non-smoking woman has worsening dyspnea, loud P2, and increased pulmonary vascular markings on CXR. Diagnosis and common mutation?", a: "Primary pulmonary hypertension. Common cause is a mutation in BMPR2." },
  { id: "rp153", category: "Pulm Pharm", q: "Treatment options for pulmonary hypertension?", a: "Dihydropyridine calcium channel blockers (nifedipine) in vasoreactive disease, prostaglandin I2 (epoprostenol), bosentan (endothelin-1 receptor antagonist), and PDE-5 inhibitors (sildenafil). USMLE generally will not make you pick between agents." },
  { id: "rp154", category: "Pulmonary HTN", q: "Why does Step 1 obsess over endothelin-1, and in which two vignettes is 'increased endothelin-1 activity' the answer?", a: "Endothelin-1 is a potent vasoconstrictor, so increased activity correlates with pulmonary hypertension (which is why bosentan works). It is the answer both in a 23-year-old with primary pulmonary HTN and in a 68-year-old with S3, bilateral crackles, JVD, and peripheral edema - CHF backs fluid into the lungs, pulmonary vessels constrict, pulmonary HTN, then the right heart fails." },
  // ===== PULM: Lung Cancer =====
  { id: "rp155", category: "Lung Cancer", q: "Which lung cancers are central vs peripheral?", a: "Central sounds like 'Sentral' -> Squamous cell and Small cell. Peripheral -> adenocarcinoma and large cell." },
  { id: "rp156", category: "Lung Cancer", q: "A 45-year-old non-smoking woman has an apical/peripheral lung mass and nothing else. Most likely cancer?", a: "Adenocarcinoma - classically female non-smokers with a peripheral lesion." },
  { id: "rp157", category: "Lung Cancer", q: "A 45-year-old non-smoker has a peripheral lung mass, proximal muscle weakness, increased CK, and a rash on the shoulders. Diagnosis?", a: "Paraneoplastic dermatomyositis secondary to bronchogenic adenocarcinoma." },
  { id: "rp158", category: "Lung Cancer", q: "A 45-year-old non-smoker has a lung mass plus thrombosis. Which cancer?", a: "Adenocarcinoma. Cancer generally is hypercoagulable, but adenocarcinomas especially - Trousseau sign of malignancy (migratory thrombophlebitis) is characteristic and is not limited to pancreatic head adenocarcinoma." },
  { id: "rp159", category: "Lung Cancer", q: "A 45-year-old long-time smoker has shooting groin pain. Diagnosis, and what is her PTH level?", a: "Ureterolithiasis from hypercalcemia due to PTHrP secretion by bronchogenic SQUAMOUS cell carcinoma. PTH is DECREASED - suppressed by the high PTHrP." },
  { id: "rp160", category: "Lung Cancer", q: "Gross specimen shows a large, cavitating, central lesion. Diagnosis?", a: "Squamous cell carcinoma - cavitations are common." },
  { id: "rp161", category: "Lung Cancer", q: "A 45-year-old with lung cancer had stabbing flank pain months ago and now presents confused. Diagnosis?", a: "Hypercalcemic crisis - squamous cell carcinoma secreting PTHrP with a history of nephrolithiasis. High calcium causes delirium." },
  { id: "rp162", category: "Lung Cancer", q: "A 45-year-old smoker has a central coin lesion, violaceous abdominal striae, and K of 3.0. Diagnosis, and why is potassium low?", a: "Small cell carcinoma with ectopic ACTH. Chronically high cortisol acts like aldosterone at the distal kidney and secretes K - seen only in ongoing Cushing syndrome." },
  { id: "rp163", category: "Lung Cancer", q: "Early-stage small cell lung cancer plus a wobbly gait. Mechanism?", a: "Autoimmune - paraneoplastic anti-Hu and anti-Yo antibodies causing cerebellar dysfunction. Small cell causes many neuronal paraneoplastic syndromes." },
  { id: "rp164", category: "Lung Cancer", q: "A 45-year-old with a central lung lesion is confused and has increased urinary osmolality. Diagnosis?", a: "SIADH from small cell carcinoma - low serum sodium plus high urine osmolality. Sodium derangement in either direction, and high calcium, can cause delirium." },
  { id: "rp165", category: "Lung Cancer", q: "A long-time smoker has difficulty rising from a chair but succeeds after multiple attempts. Location of the pathology?", a: "Neuromuscular junction - Lambert-Eaton from small cell, antibodies against presynaptic voltage-gated calcium channels. Strength improves with repeated use." },
  { id: "rp166", category: "Lung Cancer", q: "A 45-year-old non-smoker has episodic flushing, wheezing, dyspnea, and a coin lesion on CXR. Diagnosis and cell of origin?", a: "Bronchial carcinoid tumor, arising from bronchial Kulchitsky cells (neuroendocrine). Small blue cells on biopsy." },
  { id: "rp167", category: "Lung Cancer", q: "A 33-year-old with a recent molar pregnancy, very high beta-hCG, and new dry cough has multiple peripheral densities on CXR. Diagnosis?", a: "Metastatic choriocarcinoma - it loves to metastasize to the lungs and can progress from a hydatidiform mole." },
  { id: "rp168", category: "Lung Cancer", q: "Lung cancer screening criteria?", a: "Annual low-dose chest CT if ALL are true: age 55-80, more than 30 pack-year history, and smoked within the past 15 years." },
  // ===== PULM: V/Q, Shunt, Dead Space =====
  { id: "rp169", category: "Gas Exchange", q: "A 3-year-old swallows a peanut. Where does it go?", a: "Superior segment of the right lower lobe if supine; inferior segment of the right lower lobe if upright. The right mainstem bronchus is shorter and straighter." },
  { id: "rp170", category: "Gas Exchange", q: "Explain physiologic V/Q mismatch in a healthy upright lung.", a: "Both ventilation and perfusion increase from apex to base, but perfusion increases MORE, so V/Q is low at the bases (~0.6) and high at the apices (~3.0)." },
  { id: "rp171", category: "Gas Exchange", q: "Do most lung pathologies raise or lower V/Q, and what is the exception?", a: "The overwhelming majority DECREASE V/Q - COPD, CF, asthma - because ventilation drops relative to perfusion even with hypoxic vasoconstriction. Pulmonary embolism is the opposite: V/Q is HIGH because perfusion is blocked to normally ventilated lung." },
  { id: "rp172", category: "Gas Exchange", q: "Shunt vs dead space - define both.", a: "Shunt: decreased V/Q severe enough to decompensate arterial oxygen - always pathologic (decreased V/Q alone can be physiologic, e.g. 0.6 at the bases). Dead space: increased V/Q, which need not be pathologic (~3.0 at the apices)." },
  { id: "rp173", category: "Gas Exchange", q: "Four types of dead space?", a: "Alveolar: natural high V/Q in the alveoli, apices vs bases. Anatomic: airways that are ventilated but do not exchange gas - trachea, bronchi, terminal bronchioles (exchange begins at the respiratory bronchioles). Physiologic: anatomic plus alveolar. Pathologic: classically pulmonary embolism, also amniotic fluid, fat, and air emboli - blood flow blocked so V/Q rises." },
  { id: "rp174", category: "Gas Exchange", q: "Why is a pulmonary shunt called a right-to-left process?", a: "Deoxygenated blood from poorly ventilated lung mixes with oxygenated blood from good lung, so net arterial oxygenation falls - a right-to-left effect. It is not a cardiac R-to-L shunt; the mixing happens at the pulmonary venules." },
  { id: "rp175", category: "Gas Exchange", q: "Why does supplemental oxygen fail to fix a shunt?", a: "The obstructed area contributes a 'zero' for oxygen that gets averaged in with the rest of the lung. Even if remaining alveoli are maximally oxygenated, the average arterial pO2 stays low. In COPD or asthma it is many tiny mini-shunts - lots of little zeros." },
  { id: "rp176", category: "Gas Exchange", q: "What does the A-a gradient tell you, and what is normal?", a: "A = alveolar oxygen, a = arterial oxygen; normal is 5-10 mmHg. HIGH A-a gradient = low arterial O2 despite good alveolar O2, so something impedes gas exchange. NORMAL A-a gradient = low arterial O2 because alveolar O2 is low, i.e. the patient simply is not breathing enough." },
  { id: "rp177", category: "Gas Exchange", q: "Which agents classically give a NORMAL A-a gradient, and what is the trap?", a: "Opioids, benzodiazepines, barbiturates - respiratory depression. The trap: they may state a normal respiratory rate of 12 and the answer is still normal A-a gradient, because depth of respiration also matters. Same for a patient being weaned off a ventilator with pCO2 of 70. Per Mehlman, do not memorize 'lung pathology = high A-a gradient'; pulmonary edema IS high A-a gradient (transudate impedes exchange), but the USMLE slams students with normal A-a." },
  { id: "rp178", category: "Respiratory Failure", q: "Type I vs type II respiratory failure?", a: "Type I: low pO2, LOW pCO2. Type II: low pO2, HIGH pCO2. The pCO2 (normal 33-44) is the giveaway of ventilation state - pO2 70 with pCO2 55 means 'alveolar hypoventilation' is the cause of hypoxemia." },
  { id: "rp179", category: "Respiratory Failure", q: "Why does CO2 usually move opposite to respiratory rate, and why can a high RR not fix hypoxemia?", a: "CO2 diffuses quickly, O2 diffuses slowly. So with a high RR, CO2 still gets out (pCO2 low), but O2 cannot be pushed across a shunt or pathologic dead space fast enough, so pO2 stays low. High RR generally means low pCO2 and vice versa." },
  { id: "rp180", category: "Respiratory Failure", q: "ABG in an acute asthma attack, and why?", a: "Low pO2, low pCO2, normal bicarb, high pH - type I failure. RR is high (28/min) so CO2 blows off; O2 is low because bronchospasm and secretions block the slow-diffusing O2; bicarb is unchanged because it is acute (takes 12-24 hours to move, same as at altitude); pH is high from acute respiratory alkalosis." },
  { id: "rp181", category: "Respiratory Failure", q: "Asthma attack 30-45 minutes in: low pO2, NORMAL pCO2, normal bicarb, normal pH. What do you do?", a: "Intubate. The low O2 says she is still in distress, but the rising CO2 and normalizing pH mean the respiratory rate is falling from FATIGUE, not improvement. She is transitioning to type II failure - next values would be low pO2, high pCO2, normal bicarb, low pH." },
  { id: "rp182", category: "Respiratory Failure", q: "ABG in pulmonary embolism vs opioid overdose?", a: "PE: low pO2, low pCO2, normal bicarb, high pH (type I) - hypoxemia from pathologic dead space with a high RR. Opioids: low pO2, high pCO2, normal bicarb, low pH (type II respiratory acidosis) from hypoventilation." },
  { id: "rp183", category: "Respiratory Failure", q: "A 57-year-old with COPD: RR 28, pO2 50, pCO2 80, bicarb 32, pH 7.27. Diagnosis?", a: "'Chronic respiratory acidosis and acute respiratory acidosis' - acute on chronic, which is how they word it. COPD patients are chronic CO2 retainers; baseline would be high CO2, high bicarb, normal pH. Emphysematous loss of alveolar septa means less surface area, so CO2 climbs even with a high RR." },
  { id: "rp184", category: "Obstructive", q: "What causes most COPD exacerbations, and what is the tangential high-yield treatment point?", a: "Most are viral, causing bronchial inflammation and further decreased gas exchange. Even so, antibiotics are ALWAYS given in COPD exacerbations, even when the patient is afebrile." },
  // ===== PULM: PFTs =====
  { id: "rp185", category: "PFTs", q: "FEV1/FVC in obstructive vs restrictive disease?", a: "Normal is >0.7. DECREASED (<0.7) in obstructive; normal or INCREASED (>0.7) in restrictive. In both, FEV1 and FVC individually fall - only the ratio differs." },
  { id: "rp186", category: "PFTs", q: "Why is FEV1/FVC preserved or increased in restrictive disease? Give the NBME word.", a: "Radial traction. Fibrosis is 'sticky' and holds the airways open, so FEV1 does not fall as much as FVC. In obstructive disease radial traction plays no role, so FEV1 falls more and the ratio drops." },
  { id: "rp187", category: "PFTs", q: "A 59-year-old with advanced COPD and lung cancer needs partial pneumonectomy; FEV1 of the left lung is 600 mL. Next best step?", a: "Measurement of FEV1 of the right lung. Minimum acceptable postoperative FEV1 for both lungs is 800 mL. High-yield on surgery shelves - just memorize it." },
  { id: "rp188", category: "PFTs", q: "Define obstructive vs restrictive lung disease mechanically, and list the common causes of each.", a: "Obstructive: air-trapping from airway obstruction with a prolonged expiratory phase - emphysema plus chronic bronchitis (COPD), asthma. Restrictive: decreased ability to expand (decreased compliance) with a normal expiratory component - autoimmune fibrosis (RA, systemic sclerosis diffuse and CREST, sarcoidosis), prior chest radiation (Hodgkin), pneumoconioses, ankylosing spondylitis, obesity, neuromuscular disease (myasthenia gravis, Guillain-Barre)." },
  { id: "rp189", category: "PFTs", q: "Lung volumes in obstructive vs restrictive disease?", a: "Increased in obstructive, decreased in restrictive." },
  { id: "rp190", category: "PFTs", q: "What is DLCO and when is it increased?", a: "Diffusion capacity of the lung for carbon MONOXIDE - the difference in partial pressures of inspired vs expired CO. Decreased in most lung pathology but INCREASED in asthma. So if a hard vignette says DLCO is down, it is not asthma." },
  { id: "rp191", category: "PFTs", q: "A 72-year-old woman's lung function is compared with 20-year-olds. What three changes are expected?", a: "Residual volume INCREASED, arterial pO2 DECREASED, A-a gradient INCREASED. People develop obstructive-type changes with age, likely from a lifetime of inhaled particulates." },
  // ===== PULM: Obstructive Disease =====
  { id: "rp192", category: "Obstructive", q: "A 38-year-old smoker is compared with non-smokers. What three changes are expected?", a: "Mucus production and secretion INCREASED; airway cilia activity DECREASED; alveolar macrophage function DECREASED. Insidiously high-yield for Step 1." },
  { id: "rp193", category: "Obstructive", q: "A 59-year-old with a 70-pack-year history - which cell is most likely abnormal?", a: "Pseudostratified columnar epithelial cells - they are the ciliated cells of the respiratory tract, and cilia function is decreased. Wrong answers offered: alveolar macrophages, type I/II pneumocytes, alveolar endothelial cells." },
  { id: "rp194", category: "Obstructive", q: "Definition of chronic bronchitis and its most common cause?", a: "Productive cough every day for more than 3 months in a year, for at least two consecutive years. Most common cause is smoking." },
  { id: "rp195", category: "Obstructive", q: "A 57-year-old with COPD on ipratropium has 4 days of productive cough, afebrile, HR 110, RR 22, O2 sat 90%, decreased breath sounds, CXR with hyperinflation. Diagnosis?", a: "Bronchitis - acute bronchitis, usually viral. That is the NBME answer." },
  { id: "rp196", category: "Obstructive", q: "Classic way to differentiate COPD from asthma?", a: "In asthma, spirometric impairment is largely REVERSIBLE with albuterol; in COPD reversal is modest at best. 'Flattened diaphragm' (hyperinflation) is the classic COPD CXR descriptor - rare in asthma." },
  { id: "rp197", category: "Obstructive", q: "Centri-acinar vs pan-acinar emphysema?", a: "Centri-acinar = smoking. Pan-acinar = alpha-1 antitrypsin deficiency." },
  { id: "rp198", category: "Obstructive", q: "A 32-year-old non-smoker has reduced lung function, a 40-year-old brother with COPD, and a father who died of alcoholic liver disease. Diagnosis?", a: "Alpha-1 antitrypsin deficiency. The enzyme is made in the liver and breaks down elastase; deficiency gives pan-acinar emphysema in a non-smoker plus hepatic cirrhosis (alcohol worsens the liver prognosis). Codominant inheritance." },
  { id: "rp199", category: "Obstructive", q: "When is bronchiectasis the answer, and what are the causes?", a: "'Cups and cups of foul-smelling sputum' - that is 8 out of 10 presentations. Destruction of bronchiolar musculature -> ectatic airways; NBME phrases it as 'loss of elastic support to the walls of the bronchioles.' Most common cause worldwide is TB; in Western countries CF; smoking is ubiquitous." },
  { id: "rp200", category: "Obstructive", q: "A child has 6-12 months of non-productive cough and a linear/streaky opacity in the right middle lobe. Diagnosis?", a: "Bronchiectasis - 'right middle lobe syndrome.' The hard pediatric presentation, roughly 1 in 10 bronchiectasis questions, with no mention of copious sputum." },
  { id: "rp201", category: "Obstructive", q: "A 43-year-old had a lung transplant months ago and now has declining lung function, mild diaphragm flattening, and air-trapping on CT. Diagnosis?", a: "Bronchiolitis obliterans (constrictive bronchiolitis, 'popcorn lung'). It is the obstructive disease that progressively appears after lung transplant (75%) or bone marrow transplant; also toxic fumes and e-cigarettes. Biopsy confirms; irreversible, though steroids may help. Do not confuse with COP/BOOP." },
  // ===== PULM: Asthma =====
  { id: "rp202", category: "Asthma", q: "A 34-year-old has a non-productive cough and a NORMAL CXR. What is the mechanism the NBME wants?", a: "'Activation of mast cell' - asthma." },
  { id: "rp203", category: "Asthma", q: "Which drug is used to help diagnose asthma?", a: "Methacholine (muscarinic agonist) - it reproduces symptoms. Never use during an acute attack." },
  { id: "rp204", category: "Asthma", q: "Outpatient asthma treatment ladder?", a: "1) SABA (albuterol) -> 2) add low-dose inhaled corticosteroid -> 3) maximize ICS dose -> 4) add LABA (salmeterol). That order is universal. After the LABA, any order: nedocromil, cromolyn, zileuton, montelukast, zafirlukast. Oral corticosteroids are last resort but most effective." },
  { id: "rp205", category: "Asthma", q: "A 12-year-old with ongoing wheezing on albuterol - next best step? And separately, what is MOST likely to decrease recurrence?", a: "Next best step: add low-dose ICS. Most likely to decrease recurrence: ORAL corticosteroids. Both are true - the ladder says ICS next, but oral steroids are the most effective at reducing recurrence, and the FM NBME forms assess that distinction." },
  { id: "rp206", category: "Pulm Pharm", q: "Mechanisms: nedocromil/cromolyn, zileuton, the -lukasts?", a: "Nedocromil and cromolyn: mast cell stabilizers. Zileuton: lipoxygenase inhibitor (blocks leukotriene synthesis from arachidonic acid). Montelukast/zafirlukast: block LTC4, LTD4, LTE4 receptors." },
  { id: "rp207", category: "Pulm Pharm", q: "What does LTB4 do, and who else does the same?", a: "LTB4 induces NEUTROPHIL chemotaxis - unrelated to bronchoconstriction. Other neutrophil chemotactic agents: IL-8, kallikrein, platelet-activating factor, C5a, bacterial proteins." },
  { id: "rp208", category: "Asthma", q: "A 16-year-old snowboards, takes a pain reliever for sore muscles, and next day wheezes on the slopes. What happened, and what is on physical exam?", a: "He took aspirin - Samter triad / aspirin-exacerbated respiratory disease: aspirin-induced asthma, aspirin hypersensitivity, nasal polyps. Exam shows NASAL POLYPS. Other NSAIDs can do it but the USMLE makes it about aspirin." },
  { id: "rp209", category: "Asthma", q: "Why would aspirin cause asthma?", a: "Arachidonic acid goes down either the cyclooxygenase or lipoxygenase pathway. Knock out COX with aspirin -> more arachidonic acid shunted down lipoxygenase -> more leukotrienes -> more bronchoconstriction. Treat recurrence with zileuton or a -lukast." },
  { id: "rp210", category: "Asthma", q: "A 10-year-old has diffuse wheezes and sputum with eosinophils and Charcot-Leyden crystals. What mediator is implicated?", a: "Leukotriene C4. LTC4, LTD4, and LTE4 all bronchoconstrict; LTB4 does neutrophil chemotaxis. Charcot-Leyden crystals are made of the eosinophil protein galectin-10." },
  { id: "rp211", category: "Pulm Pharm", q: "What is omalizumab and when is it used?", a: "Monoclonal antibody against IgE, for intractable severe asthma unresponsive to oral steroids, in patients with eosinophilia and high IgE. Rarely used in practice." },
  { id: "rp212", category: "Asthma", q: "Acute asthma management in the emergency setting?", a: "Inhaled corticosteroids have NO role in acute asthma - that is the single most important point. Give oxygen first (any depressed O2 sat on the USMLE -> oxygen), plus nebulized albuterol, then IV steroids." },
  { id: "rp213", category: "Upper Airway", q: "A 25-year-old has runny nose and eyes in spring with cobblestoning of the nasal mucosa. Diagnosis and treatment?", a: "Allergic rhinitis ('cobblestoning' is buzzy but used on the NBME). Treat by avoiding the allergen; first-line medication is intranasal corticosteroids, second-line oral or intranasal antihistamines (loratadine)." },
  // ===== PULM: Restrictive + Interstitial =====
  { id: "rp214", category: "Restrictive", q: "What is the most important CXR/CT descriptor for restrictive lung disease?", a: "Reticulonodular or reticular pattern - colloquially honeycombing. Memorize it as equal to restrictive lung disease." },
  { id: "rp215", category: "Restrictive", q: "A 34-year-old has a non-productive cough and hilar nodularity on CXR. Diagnosis, biopsy, treatment, and the calcium story?", a: "Sarcoidosis - biopsy shows NON-CASEATING granulomas; CXR has bihilar lymphadenopathy; treat with steroids. The granulomas make 1-alpha-hydroxylase -> more active 1,25-(OH)2-D3 -> increased gut Ca and PO4 absorption -> high Ca (PO4 may be normal), LOW fecal calcium (asked on NBME), and suppressed PTH." },
  { id: "rp216", category: "Restrictive", q: "A 34-year-old hay farmer has progressive dyspnea over months and clubbing. Diagnosis and biopsy?", a: "Hypersensitivity pneumonitis - acute, subacute, or chronic. Antigens: thermophilic Actinomycetes (hay, sugarcane), non-tuberculous mycobacteria (hot tub lung, on NBME), bird fancier's lung, coffee worker's lung. Biopsy shows multinucleated giant cells." },
  { id: "rp217", category: "Restrictive", q: "A 43-year-old with rheumatoid arthritis has 6 months of dyspnea and a reticulonodular pattern on CT. What term does the NBME want?", a: "Usual interstitial pneumonia (UIP) - scarring and fibrosis of the lungs. If idiopathic, it is called idiopathic pulmonary fibrosis, but IPF is still UIP. Treat 'UIP' as synonymous with pulmonary fibrosis." },
  { id: "rp218", category: "Restrictive", q: "Drugs causing pulmonary fibrosis?", a: "Methotrexate, amiodarone, bleomycin, busulfan, nitrofurantoin. In an RA patient with UIP it is hard to know whether it is methotrexate, rheumatoid lung, or both." },
  { id: "rp219", category: "Restrictive", q: "A 57-year-old with dermatomyositis had fever and pneumonia weeks ago that has not resolved despite multiple antibiotics, with negative sputum cultures. Diagnosis?", a: "Cryptogenic organizing pneumonia (formerly BOOP). Pneumonia-like presentation in autoimmune disease (dermatomyositis, RA); CXR resembles atypical pneumonia; CT shows reverse-halo sign in 20%; Masson bodies on biopsy confirm; treat with steroids. 'Organizing' means alveolar exudates persist and fibrose." },
  { id: "rp220", category: "Restrictive", q: "A 28-year-old with asthma has recurrent lung infections and skin testing positive for Aspergillus antigen. Diagnosis?", a: "Allergic bronchopulmonary aspergillosis - usually in patients with asthma or cystic fibrosis." },
  { id: "rp221", category: "Pulm Infection", q: "A 34-year-old HIV-positive man has a nodular density in the right upper lobe. Next best step and likely diagnosis?", a: "Biopsy of the mass. Likely aspergilloma (fungus ball), with increased risk if there is a history of TB since it can occupy old cavities." },
  // ===== PULM: Pneumoconioses =====
  { id: "rp222", category: "Pneumoconioses", q: "Asbestosis - who gets it, what is on CXR and biopsy, and which cell causes the fibrosis?", a: "Shipbuilding, plumbing, construction/insulation, roofing. Supradiaphragmatic and pleural plaques ('soft tissue density' on 2CK NBME) that can calcify; biopsy may show ferruginous bodies (hemosiderin deposited by macrophages trying to digest fibers). The cell responsible for the fibrosis is the MACROPHAGE." },
  { id: "rp223", category: "Pneumoconioses", q: "Anthracosis - who gets it and what pattern on spirometry?", a: "Coalminer's lung; carbon deposition, black lungs grossly; also what city-dwellers develop by old age. OBSTRUCTIVE pattern on spirometry." },
  { id: "rp224", category: "Pneumoconioses", q: "Silicosis - who gets it, CXR finding, and the TB caveat?", a: "Stone quarry workers; eggshell calcifications; RESTRICTIVE on spirometry. Increased TB risk from decreased alveolar macrophage function - do a PPD at new diagnosis, and do NOT give anti-TNF-alpha agents (they further increase TB risk)." },
  { id: "rp225", category: "Pneumoconioses", q: "Berylliosis, byssinosis, bagassosis, Caplan syndrome - define each.", a: "Berylliosis: aeronautical industry, granulomatous, so steroids may help (they do not help in the other pneumoconioses). Byssinosis: hemp / textile fibers. Bagassosis: sugarcane, antigen is thermophilic Actinomycetes. Caplan syndrome: pneumoconiosis plus rheumatoid arthritis, restrictive." },
  // ===== PULM: Alveolar Cells + Neonatal =====
  { id: "rp226", category: "Alveolar Cells", q: "Function of type I vs type II pneumocytes, and what are Clara cells?", a: "Type I: 95% of alveolar surface area, simple squamous, does gas exchange. Type II: fewer, interspersed; make surfactant in lamellar bodies and act as the stem cells of the lung, restoring type I cells after injury as long as basement membranes are intact. Clara cells secrete glycosaminoglycans to protect the bronchiolar lining." },
  { id: "rp227", category: "Alveolar Cells", q: "A 27-year-old has an inhalation injury from a house fire. Destruction of which structure most precludes restoration of normal lung architecture?", a: "Basement membranes. Intact basement membranes are necessary for complete healing after lung injury or infection - the same reason a residual lesion persists months after a treated pulmonary abscess ('failure of maintenance of basement membranes')." },
  { id: "rp228", category: "Neonatal Pulm", q: "A child born at 28 weeks is dyspneic. Two NBME-phrased answers, and the lab ratio?", a: "'Deficiency of lamellar bodies' and 'deficiency of surfactant protein D' - neonatal respiratory distress syndrome / hyaline membrane disease. Lecithin (dipalmitoyl phosphatidylcholine) to sphingomyelin ratio should be >2." },
  { id: "rp229", category: "Neonatal Pulm", q: "A neonate born at 38 weeks by C-section has RR 70 with mild bilateral hyperinflation and prominent perihilar interstitial markings. Diagnosis and mechanism?", a: "Transient tachypnea of the newborn - the answer when it 'sounds like NRDS but the kid is term.' Seen after C-sections and fast vaginal deliveries; delayed absorption of fetal lung fluid by pulmonary lymphatics. Treatment is supportive." },
  { id: "rp230", category: "Neonatal Pulm", q: "A neonate born at 26 weeks needed weeks of oxygen and is now on home oxygen. Increased risk of what three things?", a: "Bronchopulmonary dysplasia, retinopathy of prematurity, germinal matrix bleed - all seen with neonatal oxygen therapy." },
  { id: "rp231", category: "Neonatal Pulm", q: "A newborn has decreased bowel sounds in the abdomen with tracheal shift to the right, or bowel sounds heard in the left chest. Diagnosis and mechanism?", a: "Congenital diaphragmatic hernia - incomplete formation of the pleuroperitoneal membranes. Occurs on the LEFT, with bowel herniating into the left hemithorax." },
  { id: "rp232", category: "Neonatal Pulm", q: "A 12-hour-old newborn has excessive oral secretions and coughing after the first feed, resolving with suctioning; the pregnancy had polyhydramnios. Next best step and diagnosis?", a: "Insert a nasogastric tube. Diagnosis is tracheoesophageal fistula." },
  { id: "rp233", category: "Neonatal Pulm", q: "A 12-hour-old newborn turns blue while breastfeeding and pink again when crying. Diagnosis and syndrome?", a: "Choanal atresia - CHARGE syndrome: Coloboma, Heart defects, Atresia of the choanae, Retardation, Genitourinary abnormalities, Ear abnormalities/deafness." },
  // ===== PULM: Pediatric Airway =====
  { id: "rp234", category: "Peds Airway", q: "A 10-month-old has a fever of 101F and bilateral wheezes. Diagnosis and treatment?", a: "RSV bronchiolitis. Treatment is supportive - ribavirin and palivizumab are almost always wrong on actual NBME assessments." },
  { id: "rp235", category: "Peds Airway", q: "An 8-year-old is leaning forward in a tripod position and drooling. Diagnosis, x-ray, and management?", a: "Epiglottitis from Haemophilus influenzae type B. Thumbprint sign on neck x-ray. IMMEDIATE intubation even if stable (the airway can obstruct at any moment), ceftriaxone for the patient, rifampin for close contacts. Usually in unvaccinated/immigrant children." },
  { id: "rp236", category: "Peds Airway", q: "An 8-year-old has a hoarse, barking cough that improves in the cold air outside. Diagnosis, x-ray, treatment?", a: "Croup (laryngotracheobronchitis) from parainfluenza virus. Seal-like barking cough; steeple sign (subglottic narrowing) on neck x-ray. Supportive; if forced to pick a treatment, nebulized racemic epinephrine." },
  { id: "rp237", category: "Peds Airway", q: "An 8-year-old recovered from influenza two weeks ago and now has fever, barking cough, and inspiratory stridor. Diagnosis and workup?", a: "Bacterial tracheitis from Staph aureus. Diagnose with bronchoscopy; treat with antibiotics." },
  { id: "rp238", category: "Peds Airway", q: "An 8-month-old has stridor that improves with neck extension - versus stridor that improves when prone or upright. Two diagnoses?", a: "Improves with neck extension: vascular ring (aorta and surrounding vessels encircle the esophagus and/or trachea). Improves prone or upright: laryngomalacia, the most common cause of stridor in peds - soft upper laryngeal cartilage collapses on inhalation." },
  { id: "rp239", category: "Peds Airway", q: "A 2-year-old has stridor and laryngoscopy shows small growths on the larynx. Cause?", a: "HPV 6/11 - laryngeal papillomatosis." },
  { id: "rp240", category: "Peds Airway", q: "A 3-year-old snores loudly, mouth-breathes, has a 1/6 holosystolic murmur with loud S2, cardiomegaly with increased pulmonary vascular markings, and RV hypertrophy with mild tricuspid regurgitation. Long-term management?", a: "Adenoidectomy and tonsillectomy. Upper airway obstruction can cause obstructive lung disease with cor pulmonale - loud S2 and increased pulmonary markings signal pulmonary HTN, and tricuspid regurgitation can accompany it. High-yield for the Peds shelf." },
  // ===== PULM: CF and Cilia =====
  { id: "rp241", category: "Cystic Fibrosis", q: "Highest-yield points about cystic fibrosis?", a: "Autosomal recessive, chromosome 7, CFTR gene - a chloride channel that secretes chloride in lungs and pancreas and reabsorbs chloride in sweat glands. DF508 (deletion of phenylalanine at 508) is most common; mutated CFTR is retained in the rough ER. Sweat chloride >60 mEq/L is most diagnostic, more than genotyping. Negative transepithelial potential difference across nasal epithelium. Neonates screened with immunoreactive trypsinogen." },
  { id: "rp242", category: "Cystic Fibrosis", q: "Pneumonia organisms in CF by age, the infertility issue, and two drugs?", a: "Before age 10 Staph aureus eclipses Pseudomonas; after age 10 Pseudomonas eclipses Staph. Male infertility from congenital bilateral absence of the vas deferens. Dornase alfa is a deoxyribonuclease that thins secretions; ivacaftor is a CFTR potentiator." },
  { id: "rp243", category: "Cystic Fibrosis", q: "A 32-year-old has recurrent lung infections, 2 years of infertility (his wife has children from a prior marriage), and immotile sperm. Diagnosis and how does it differ from CF?", a: "Kartagener syndrome (primary ciliary dyskinesia) - dynein arm defect; a cilium has a 9x2 microtubule arrangement. Associated with dextrocardia / situs inversus. Sperm are present but IMMOTILE, in contrast to CF where there is no sperm at all due to CBAVD." },
  // ===== PULM: TB =====
  { id: "rp244", category: "TB", q: "How do you diagnose TB, step by step?", a: "PPD first. If there is a history of BCG, do an interferon-gamma release assay instead - never both. If PPD is negative, repeat after one week (repeats within a week can give a false positive from a booster reaction); negative again means no further studies. If IGRA is negative, no further studies. If PPD or IGRA is positive, get a CXR - do not repeat a positive PPD. CXR negative -> treat latent TB; CXR positive -> treat active TB." },
  { id: "rp245", category: "TB", q: "PPD induration cutoffs - who is positive at 5, 10, and 15 mm?", a: "Measure INDURATION only, erythema does not count. 5+ mm: recent contact with active TB, HIV positive, organ transplant recipients, chronic prednisone (>15 mg/day for >1 month) or anti-TNF-alpha use, CXR findings consistent with TB. 10+ mm: immigrants (not from Western countries), IV drug users, healthcare/prison/homeless shelter workers, TB lab personnel, children under 4. 15+ mm: everyone." },
  { id: "rp246", category: "TB", q: "Treatment of latent TB, and why pyridoxine?", a: "9 months INH plus pyridoxine (vitamin B6) - that is what Steps 1 and 2CK want. Alternatives: 4 months rifampin, or 3 months INH plus rifapentine plus pyridoxine. B6 is given with INH to prevent B6 deficiency." },
  { id: "rp247", category: "TB", q: "Treatment of active TB?", a: "RIPE - rifampin, INH, pyrazinamide, ethambutol - for 2 months, then rifampin plus INH for 4 more months (6 months total). Add pyridoxine (annoyingly similar sounding to pyrazinamide)." },
  // ===== PULM: Pneumonia =====
  { id: "rp248", category: "Pulm Infection", q: "A 32-year-old has a fever of 101F and bilateral interstitial infiltrates on CXR. Diagnosis?", a: "Mycoplasma pneumoniae - the most common cause of atypical pneumonia after viruses, classically bilateral." },
  { id: "rp249", category: "Pulm Infection", q: "A 32-year-old has fever, lobar consolidation, and dullness to percussion. Diagnosis, and the gram stain?", a: "Streptococcus pneumoniae - gram-POSITIVE diplococci. Do not confuse with Neisseria gonorrhoeae and meningitidis, which are gram-negative diplococci." },
  { id: "rp250", category: "Pulm Infection", q: "A 32-year-old has fever and lobar consolidation WITH interstitial markings. Diagnosis?", a: "Mycoplasma - on a 2CK NBME where Strep pneumo was not listed. Implication: if the question says 'interstitial,' that beats distribution/location." },
  { id: "rp251", category: "Pulm Infection", q: "A 44-year-old alcoholic has fever and an air-fluid level on CXR. Diagnosis, treatment, and the organisms?", a: "Pulmonary abscess; treat with clindamycin. The air-fluid level is a circle where the bottom half is pus (radiopaque) and the top half is air (radiolucent). Due to aspiration of oropharyngeal anaerobes - Bacteroides, Mobiluncus, Peptostreptococcus." },
  { id: "rp252", category: "Pulm Infection", q: "A 44-year-old alcoholic has fever plus lobar consolidation - with thick red sputum, or with extremely foul-smelling sputum. Two diagnoses?", a: "Thick red 'currant jelly' sputum -> Klebsiella pneumoniae (mucoid colonies, common in aspiration pneumonia, increased risk in alcoholics). Extremely foul-smelling -> Bacteroides pneumonia." },
  { id: "rp253", category: "Pulm Infection", q: "Match the exposure: diarrhea plus hyponatremia; cattle farmer; pet rabbit; bird owner.", a: "Pneumonia plus diarrhea plus hyponatremia -> Legionella pneumophila. Cattle farmer -> Coxiella burnetii. Pet rabbit -> Francisella tularensis. Bird owner -> Chlamydia psittaci." },
  { id: "rp254", category: "Pulm Infection", q: "Pneumonia in a 2-week-old whose ophthalmia neonatorum was treated a week ago. Diagnosis and route?", a: "Chlamydia trachomatis pneumonia - chlamydial neonatal conjunctivitis drains through the nasolacrimal duct into the nasopharynx and then the lung." },
  { id: "rp255", category: "Pulm Infection", q: "Pneumonia right after recovering from influenza - and lobar pneumonia in an HIV patient?", a: "Post-viral pneumonia -> Staph aureus (same logic as post-viral bacterial tracheitis). Lobar pneumonia in HIV -> Strep pneumo, NOT Pneumocystis." },
  { id: "rp256", category: "Pulm Infection", q: "An HIV patient has bilateral ground-glass opacities. Next best step, diagnosis, treatment?", a: "Bronchoalveolar lavage with silver staining of the yeast -> Pneumocystis jirovecii -> treat with TMP/SMX." },
  { id: "rp257", category: "Pulm Infection", q: "Empiric treatment for community-acquired pneumonia, and if the patient had antibiotics in the last 3 months?", a: "Azithromycin (macrolide) - covers atypicals and S. pneumo. If antibiotics within 3 months, use a respiratory fluoroquinolone such as levofloxacin." },
  { id: "rp258", category: "Pulm Infection", q: "Inpatient CAP treatment - non-ICU, ICU, and septic?", a: "Non-ICU: fluoroquinolone, OR beta-lactam plus macrolide. ICU: beta-lactam plus either a macrolide or a fluoroquinolone. Septic: ceftriaxone with or without vancomycin - ceftriaxone monotherapy is all over the 2CK NBMEs for sepsis, and ceftriaxone plus vancomycin is the answer on a newer form for septic CAP. In children under 6, use cefotaxime instead of ceftriaxone (less bilirubin displacement from albumin)." },
  { id: "rp259", category: "Pulm Infection", q: "When is pneumonia hospital-acquired, and how does treatment differ?", a: "Symptoms starting more than 48 hours after admission. HAP and VAP must cover MRSA and Pseudomonas: vancomycin plus a 3rd or 4th generation cephalosporin (ceftazidime, cefepime - both anti-Pseudomonal), piperacillin/tazobactam, amikacin for Pseudomonas, ceftaroline or ceftobiprole (5th gen) for MRSA, meropenem or imipenem/cilastatin." },
  // ===== PULM: COPD Management =====
  { id: "rp260", category: "Pulm Pharm", q: "First-line treatment in COPD?", a: "SABA or SAMA (short-acting muscarinic antagonist, ipratropium). On a 2CK NBME the answer is straight-up ipratropium - home oxygen and pulmonary rehabilitation are wrong for first-line." },
  { id: "rp261", category: "Obstructive", q: "When is home oxygen indicated in COPD, and what is the number-one way to decrease mortality?", a: "Home oxygen when arterial pO2 <60 mmHg, or <55 mmHg if the patient has cor pulmonale. Number-one mortality reducer is smoking cessation; if the patient already quit, home oxygen therapy (which does decrease mortality, but only per those criteria)." },
  { id: "rp262", category: "Respiratory Failure", q: "A 48-year-old with BMI 45 snores loudly. What lab finding is most likely, and why?", a: "Increased serum bicarbonate. Obesity hypoventilation syndrome -> chronically high CO2 -> compensatory rise in bicarb (chronic respiratory acidosis)." },
  // ===== PULM: Pleura =====
  { id: "rp263", category: "Pleura", q: "Pleural effusion in someone with pneumonia - name it, and what predicts progression to empyema?", a: "Parapneumonic effusion (exudative, secondary to lung infection). Decreased pleural fluid pH (<7.1) is most predictive of progression to empyema." },
  { id: "rp264", category: "Pleura", q: "What is an empyema, versus an abscess?", a: "Empyema is pus in a PREEXISTING cavity - here the pleural space. An abscess is pus where there was no preexisting cavity, e.g. the forearm." },
  { id: "rp265", category: "Pleura", q: "Light's criteria for an exudative effusion?", a: "Any one of: pleural fluid to serum protein ratio >0.5; pleural fluid to serum LDH ratio >0.6; pleural fluid LDH greater than two-thirds the upper limit of serum LDH. Qualitatively, exudates also have higher cell counts, and glucose can be low in infective (parapneumonic) causes." },
  { id: "rp266", category: "Pleura", q: "A 44-year-old with a long smoking history has dullness to percussion two-thirds up the lung field. Diagnosis, and the three common causes of effusion?", a: "Malignant pleural effusion. Malignancy, congestive heart failure, and infection are the common causes." },
  { id: "rp267", category: "Pleura", q: "A 32-year-old woman has an ovarian fibroma, ascites, and hydrothorax. Diagnosis?", a: "Meigs syndrome." },
  // ===== PULM: PE and Pneumothorax =====
  { id: "rp268", category: "PE", q: "Treatment sequence for suspected pulmonary embolism, including in pregnancy?", a: "Heparin BEFORE the spiral CT of the chest. If pregnant, do a V/Q scan instead of CT - sufficient for the USMLE." },
  { id: "rp269", category: "PE", q: "When is an IVC filter the answer?", a: "When the patient gets a PE while already anticoagulated (warfarin, dabigatran) AND the spiral CT is already done. So: on warfarin plus PE -> next step CT; on warfarin plus PE with CT confirming -> next step IVC filter." },
  { id: "rp270", category: "PE", q: "A 36-year-old has long-bone fractures and petechiae on the chest. Diagnosis?", a: "Fat embolism." },
  { id: "rp271", category: "Chest Trauma", q: "A 32-year-old basketball player has a few hours of dyspnea. Diagnosis and treatment?", a: "Spontaneous pneumothorax from a ruptured subapical bleb. Needle decompression followed by chest tube - some small pneumothoraces can be observed, but on the USMLE always treat." },
  { id: "rp272", category: "Chest Trauma", q: "A 32-year-old in a motor vehicle accident has dyspnea, low BP, decreased breath sounds on the left, and tracheal shift to the RIGHT. Diagnosis and treatment?", a: "Tension pneumothorax. Needle decompression followed by chest tube." },
  { id: "rp273", category: "Chest Trauma", q: "MVA with paradoxical breathing - chest moves outward with exhalation and inward with inhalation. Diagnosis?", a: "Flail chest." },
  { id: "rp274", category: "Chest Trauma", q: "MVA with rib fractures, underlying pulmonary infiltrates, and low O2 sats - and the version where saline worsens the sats. Diagnosis?", a: "Pulmonary contusion both times; contused lung is very sensitive to fluid overload. It is also the answer with no rib fractures when there is non-central chest pain with infiltrates under the painful area. 'White out of the lung' is Qbank buzz, not NBME." },
  { id: "rp275", category: "Chest Trauma", q: "MVA with bruising/pain over the STERNUM, with or without rib fractures - even if saline worsens the O2 sats. Diagnosis and management?", a: "Myocardial contusion. Sternal bruising/pain wins over the fluid-sensitivity clue if it is listed (this is on a 2CK NBME). Management: troponins plus monitoring for arrhythmia." },
  { id: "rp276", category: "Pulmonary Edema", q: "'Cephalization of pulmonary vasculature.' Diagnosis and mechanism?", a: "Pulmonary edema - increased hydrostatic pressure from left heart pathology. Important NBME vignette descriptor." },
  { id: "rp277", category: "ARDS", q: "An adult male with abdominal pain and a history of alcohol use has diffuse pulmonary infiltrates and low O2 sats. Diagnosis, criterion, and ventilator strategy?", a: "ARDS (here from pancreatitis). Requires pO2/FiO2 <300. Low-tidal-volume ventilation to prevent barotrauma, permissive hypercapnia, prone positioning." },
  { id: "rp278", category: "ARDS", q: "Two default ventilator answers on the USMLE?", a: "For a random ventilator question, 'increase PEEP' is almost always right. If O2 sats are improving, 'wean from ventilator.'" },
  // ===== PULM: Immune + Upper Respiratory =====
  { id: "rp279", category: "Upper Airway", q: "An 18-year-old with asthma has 2 days of right cheek tenderness and a history of several pneumonias and sinusitis episodes. Diagnosis and NBME phrasings?", a: "IgA deficiency - often listed as 'impaired humoral immunity' or 'deficiency of mucosal immunoglobulin.' Sore cheek is classic for sinusitis. Recurrent sinopulmonary infections, plus associations with Giardia, autoimmune disease (vitiligo), and atopy. Anaphylaxis with blood transfusion shows up rarely." },
  { id: "rp280", category: "Upper Airway", q: "CENTOR criteria and how to score them?", a: "1) Absence of cough, 2) fever, 3) tonsillar exudates, 4) cervical/submandibular lymphadenopathy. 0-1 point means likely viral; 2-4 means much more likely bacterial. Per Mehlman, skip the age-modified version - it makes you get USMLE questions wrong." },
  { id: "rp281", category: "Upper Airway", q: "Management by CENTOR score?", a: "0-1 point: supportive care / no treatment / warm saline gargle / acetaminophen (the latter is the answer for a 3-year-old with viral URTI and fever on Peds NBME form 2). 0-2 points: rapid Strep test; if negative, THROAT culture (not sputum culture). While waiting on the culture, send home with amoxicillin or penicillin for presumptive Strep pharyngitis." },
  { id: "rp282", category: "Upper Airway", q: "A 16-year-old who has been dating has all four CENTOR criteria. Diagnosis, test, and the beta-lactam trap?", a: "EBV mononucleosis - do a heterophile antibody (Monospot) test. EBV is the odd virus that usually presents with all four positive CENTOR criteria, which is why it is misdiagnosed as Strep. Beta-lactams in EBV cause an intense pruritic rash 7-10 days later on extensor surfaces and pressure points; EBV alone can cause a milder maculopapular rash. In a 12-year-old who develops a rash on a beta-lactam without EBV, the answer is beta-lactam allergy." },
  // ===== PULM: Oxygen Transport =====
  { id: "rp283", category: "Oxygen Transport", q: "What shifts the hemoglobin-oxygen dissociation curve to the right, and what does that mean?", a: "Increased temperature, increased 2,3-BPG, increased CO2, decreased pH, increased H+. A right shift means increased oxygen unloading at the tissues. Protons in blood are buffered by deoxygenated hemoglobin (Step 1 NBME)." },
  { id: "rp284", category: "Oxygen Transport", q: "A 50-year-old has a normal arterial pO2 but low arterial oxygen CONTENT. Why?", a: "Anemia. Oxygen content = O2 dissolved in blood (pO2) plus O2 bound to hemoglobin. If pO2 is normal, binding should be fine, so the way content stays low is low hemoglobin." },
];

export default renalPulmQuestions;
